insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MC', 'default', 'Plan de comptes sur la structure du plan comptable général', '{}'::jsonb, true, 'companies', array['MC-BS', 'MC-IS']::text[], null, 'Le Code de commerce monégasque impose un livre-journal, un inventaire annuel et la conservation des livres pendant dix ans (art. 10 à 13) mais ne prescrit aucun plan de comptes ; aucun texte monégasque lu ne rend obligatoire le plan comptable général français. Ce plan en suit la structure (classes 1 à 7, comptes à deux, trois et six chiffres) parce que les règles de taxe qu''il porte sont celles de la France (convention franco-monégasque du 18 mai 1963, art. 15, rappelée à l''art. préliminaire du CTCA) et que la pratique des entreprises de la Principauté est de s''y tenir. Cette pratique n''est pas sourcée : c''est une hypothèse du pack, dite dans README.md.', 'pcg')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

