values
  ('MC', 'MC-P-00', 'Achat exonere', '{}'::jsonb, 'Sans TVA', 'percent', 0, 'purchase', 'exempt', date '1993-01-01', null, 'Achat sans taxe : fournisseur non assujetti, opération exonérée ou hors champ. Aucune écriture de taxe.', 'E', 'VATEX-EU-132', 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-021', 'Achat 2,1 %', '{}'::jsonb, 'Taux de 2,10 %', 'percent', 2.1, 'purchase', 'domestic', date '2014-01-01', null, 'CTCA, art. 58 (premières représentations de certains spectacles), art. 59 (médicaments remboursables et préparations magistrales) et art. 95 (publications de presse) — taux de 2,10 %. Déduction : CTCA, art. 42, I.', 'S', null, 145, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-055', 'Achat 5,5 %', '{}'::jsonb, 'Autres biens et services', 'percent', 5.5, 'purchase', 'domestic', date '2014-01-01', null, 'CTCA, art. 52-0 — taux réduit de 5,5 % (denrées alimentaires destinées à la consommation humaine, énergie, livres, équipements pour personnes handicapées…). Déduction : CTCA, art. 42, I.', 'S', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-055-ENC', 'Achat de services 5,5 % — TVA déductible au décaissement', '{}'::jsonb, 'Le droit à déduction prend naissance quand la taxe devient exigible chez le prestataire, soit au paiement. Si le prestataire a opté pour les débits, MC-P-055.', 'percent', 5.5, 'purchase', 'domestic', date '2014-01-01', null, 'CTCA, art. 52-0 — taux réduit de 5,5 % (denrées alimentaires destinées à la consommation humaine, énergie, livres, équipements pour personnes handicapées…). CTCA, art. 40, 2, c) — pour les prestations de services, la taxe est exigible lors de l''encaissement des acomptes, du prix ou de la rémunération ou, sur autorisation du directeur des Services fiscaux, d''après les débits (art. A-64 de l''annexe au code). Le prestataire qui a opté pour les débits utilise le code sans « -ENC ». Déduction : CTCA, art. 42, I.', 'S', null, 141, 'vat', true, '{}'::tax_condition[], null, false, true, '445860', 'ctca', null, null, null, null),
  ('MC', 'MC-P-10', 'Achat 10 %', '{}'::jsonb, 'Autres biens et services', 'percent', 10, 'purchase', 'domestic', date '2014-01-01', null, 'CTCA, art. 52 (produits), art. 56 (hébergement, restauration, transports…) et art. 56 bis (travaux dans les logements anciens) — taux réduit de 10 %. Déduction : CTCA, art. 42, I.', 'S', null, 130, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-10-ENC', 'Achat de services 10 % — TVA déductible au décaissement', '{}'::jsonb, 'Le droit à déduction prend naissance quand la taxe devient exigible chez le prestataire, soit au paiement. Si le prestataire a opté pour les débits, MC-P-10.', 'percent', 10, 'purchase', 'domestic', date '2014-01-01', null, 'CTCA, art. 52 (produits), art. 56 (hébergement, restauration, transports…) et art. 56 bis (travaux dans les logements anciens) — taux réduit de 10 %. CTCA, art. 40, 2, c) — pour les prestations de services, la taxe est exigible lors de l''encaissement des acomptes, du prix ou de la rémunération ou, sur autorisation du directeur des Services fiscaux, d''après les débits (art. A-64 de l''annexe au code). Le prestataire qui a opté pour les débits utilise le code sans « -ENC ». Déduction : CTCA, art. 42, I.', 'S', null, 131, 'vat', true, '{}'::tax_condition[], null, false, true, '445860', 'ctca', null, null, null, null),
  ('MC', 'MC-P-20', 'Achat 20 %', '{}'::jsonb, 'Autres biens et services', 'percent', 20, 'purchase', 'domestic', date '2014-01-01', null, 'Code des taxes sur le chiffre d''affaires (CTCA), art. 51 — le taux normal de la taxe sur la valeur ajoutée est fixé à 20 %. Déduction : CTCA, art. 42, I.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-20-ENC', 'Achat de services 20 % — TVA déductible au décaissement', '{}'::jsonb, 'Le droit à déduction prend naissance quand la taxe devient exigible chez le prestataire, soit au paiement. Si le prestataire a opté pour les débits, MC-P-20.', 'percent', 20, 'purchase', 'domestic', date '2014-01-01', null, 'Code des taxes sur le chiffre d''affaires (CTCA), art. 51 — le taux normal de la taxe sur la valeur ajoutée est fixé à 20 %. CTCA, art. 40, 2, c) — pour les prestations de services, la taxe est exigible lors de l''encaissement des acomptes, du prix ou de la rémunération ou, sur autorisation du directeur des Services fiscaux, d''après les débits (art. A-64 de l''annexe au code). Le prestataire qui a opté pour les débits utilise le code sans « -ENC ». Déduction : CTCA, art. 42, I.', 'S', null, 111, 'vat', true, '{}'::tax_condition[], null, false, true, '445860', 'ctca', null, null, null, null),
  ('MC', 'MC-P-20-I', 'Achat immobilisation 20 %', '{}'::jsonb, 'Immobilisations', 'percent', 20, 'purchase', 'domestic', date '2014-01-01', null, 'CTCA, art. 42, I — la taxe qui a grevé les éléments du prix d''une opération imposable est déductible ; la déduction sur immobilisations se porte sur sa propre ligne du formulaire.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-AL-20', 'Achat autoliquidation 20 %', '{}'::jsonb, 'Assujetti non etabli, lignes 3C/08/20', 'percent', 20, 'purchase', 'domestic_reverse_charge', date '2014-01-01', null, 'CTCA, art. 62, 2 — lorsque le prestataire n''est pas établi à Monaco ou en France, la taxe est acquittée par le preneur, qui la déduit à l''art. 42, I.', 'AE', 'VATEX-EU-AE', 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-ICG-20', 'Acquisition intracom. biens 20 %', '{}'::jsonb, 'Autoliquidation, lignes 03/08/20', 'percent', 20, 'purchase', 'intracom_acquisition_goods', date '1993-01-01', null, 'CTCA, art. 2, I — l''acquisition intracommunautaire de biens est une opération imposable à Monaco ; la taxe est due par l''acquéreur au taux applicable à la livraison du même bien (art. 51 pour le taux normal) et déductible à l''art. 42, I.', 'K', 'VATEX-EU-IC', 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-P-ICS-20', 'Service intracom. recu 20 %', '{}'::jsonb, 'Autoliquidation, lignes 2A/08/20', 'percent', 20, 'purchase', 'intracom_acquisition_services', date '2010-01-01', null, 'CTCA, art. 62, 2 — lorsque le prestataire n''est pas établi à Monaco ou en France, la taxe est acquittée par le preneur, qui la déduit à l''art. 42, I.', 'K', 'VATEX-EU-IC', 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
