  ('MC', 'MC-S-20', 'Vente 20 %', '{}'::jsonb, 'Taux normal', 'percent', 20, 'sale', 'domestic', date '2014-01-01', null, 'Code des taxes sur le chiffre d''affaires (CTCA), art. 51 — le taux normal de la taxe sur la valeur ajoutée est fixé à 20 %.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-S-20-ENC', 'Prestation de services 20 % — TVA sur les encaissements', '{}'::jsonb, 'Régime de droit commun des prestations de services : la TVA est exigible à l''encaissement du prix. Pour une entreprise ayant opté pour les débits, MC-S-20.', 'percent', 20, 'sale', 'domestic', date '2014-01-01', null, 'Code des taxes sur le chiffre d''affaires (CTCA), art. 51 — le taux normal de la taxe sur la valeur ajoutée est fixé à 20 %. CTCA, art. 40, 2, c) — pour les prestations de services, la taxe est exigible lors de l''encaissement des acomptes, du prix ou de la rémunération ou, sur autorisation du directeur des Services fiscaux, d''après les débits (art. A-64 de l''annexe au code). Le prestataire qui a opté pour les débits utilise le code sans « -ENC ».', 'S', null, 11, 'vat', true, '{}'::tax_condition[], null, false, true, '445870', 'ctca', null, null, null, null),
  ('MC', 'MC-S-EXP', 'Exportation hors UE', '{}'::jsonb, 'Exoneree', 'percent', 0, 'sale', 'export', date '1993-01-01', null, 'CTCA, art. 29, 1° et 2° — exonération des livraisons de biens expédiés ou transportés hors de l''Union européenne, avec maintien du droit à déduction (art. 42, V, c).', 'G', 'VATEX-EU-G', 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-S-ICG', 'Livraison intracommunautaire', '{}'::jsonb, 'Biens, exoneree', 'percent', 0, 'sale', 'intracom_goods', date '1993-01-01', null, 'CTCA, art. 31, I, 1° — exonération des livraisons de biens expédiés ou transportés vers un autre État membre de l''Union européenne à destination d''un assujetti identifié à la TVA dans cet État ; l''état récapitulatif de l''art. 73 est la condition de l''exonération. Le droit à déduction est maintenu (art. 42, V, c).', 'K', 'VATEX-EU-IC', 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null),
  ('MC', 'MC-S-ICS', 'Service intracommunautaire', '{}'::jsonb, 'Service à un assujetti établi dans l’Union européenne, hors du champ de la taxe monégasque', 'percent', 0, 'sale', 'intracom_services', date '2010-01-01', null, 'CTCA, art. 11, 1° — le lieu d''une prestation de services à un assujetti est celui où il a son siège ou un établissement stable ; une prestation à un assujetti établi dans un autre État membre est située hors de Monaco, hors du champ de la taxe de la Principauté.', 'K', 'VATEX-EU-IC', 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'ctca', null, null, null, null)
