insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MC', 'MC-TVA', 'Déclaration de TVA mensuelle ou trimestrielle (numérotation du formulaire 3310-CA3)', array['month', 'quarter']::declaration_period[], 'month'::declaration_period, date '2014-01-01', null, 'CTCA, art. 70, 1 — tout redevable remet chaque mois à la recette des taxes une déclaration conforme au modèle prescrit par l''Administration, indiquant le montant total de ses opérations et le détail de ses opérations taxables, et acquitte la taxe exigible tous les mois ; art. 70, 2, alinéa 2 — lorsque la taxe exigible annuellement est inférieure à 4 000 €, le dépôt trimestriel est admis. La cadence mensuelle est proposée parce que la loi la donne à tout le monde ; le dépôt trimestriel est un fait sur l''entreprise, pas un défaut. L''art. 70, 5 veut une déclaration particulière par activité de nature différente.', true,'depends_on_taxpayer'::filing_deadline_rule, null, null, 'CTCA, annexe, art. A-144, 1 — le directeur des Services fiscaux répartit les redevables en catégories et fixe, pour chacune, la période du mois durant laquelle la déclaration doit être remise ; à défaut de fixation, la déclaration doit être remise avant le 25 de chaque mois. L''art. A-144, 2 reporte l''échéance au premier jour ouvrable suivant un jour férié ; l''art. 70, 2 et l''art. A-145 admettent, sur demande motivée, un délai supplémentaire d''un mois. La catégorie d''un redevable n''est pas un fait du pack : il déclare que le jour dépend du redevable plutôt qu''un jour faux pour certains.', 'ctca', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

